### 4. 重新映射 `ntdll.dll` 并替换被篡改的函数

使用以下代码从磁盘重新映射 `ntdll.dll` 并替换被篡改的函数：

```c
#include <windows.h>
#include <stdio.h>

int main() {
    HMODULE hModule = GetModuleHandle(L"ntdll.dll");
    if (hModule) {
        MEMORY_BASIC_INFORMATION mbi;
        if (VirtualQuery(hModule, &mbi, sizeof(mbi)) && mbi.RegionSize > 0) {
            printf("Current ntdll.dll base: %p\n", mbi.BaseAddress);
            printf("Current ntdll.dll size: %zu\n", mbi.RegionSize);

            // Unmap the current ntdll.dll
            if (VirtualFree(mbi.BaseAddress, mbi.RegionSize, MEM_RELEASE)) {
                printf("Unmapped current ntdll.dll\n");

                // Map the new ntdll.dll from disk
                HANDLE hFile = CreateFileA("ntdll.dll", GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
                if (hFile != INVALID_HANDLE_VALUE) {
                    DWORD fileSize = GetFileSize(hFile, NULL);
                    LPVOID pNewNtdll = VirtualAlloc(NULL, fileSize, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE);
                    if (pNewNtdll) {
                        DWORD bytesRead;
                        ReadFile(hFile, pNewNtdll, fileSize, &bytesRead, NULL);
                        CloseHandle(hFile);

                        // Replace the old ntdll.dll with the new one
                        memcpy(mbi.BaseAddress, pNewNtdll, mbi.RegionSize);
                        printf("Replaced ntdll.dll\n");
                    } else {
                        printf("Failed to allocate memory for new ntdll.dll\n");
                    }
                } else {
                    printf("Failed to open new ntdll.dll file\n");
                }
            } else {
                printf("Failed to unmap current ntdll.dll\n");
            }
        } else {
            printf("Failed to query memory information\n");
        }
    } else {
        printf("Failed to get ntdll.dll handle\n");
    }
    return 0;
}
```

