```javascript
// server.js
const express = require('express');
const WebSocket = require('ws');
const mongoose = require('mongoose');

const app = express();
const wss = new WebSocket.Server({ port: 8080 });

// MongoDB连接
mongoose.connect('mongodb://localhost:27017/c2_framework', { useNewUrlParser: true, useUnifiedTopology: true });

// 定义任务模型
const TaskSchema = new mongoose.Schema({
    id: String,
    description: String,
    status: String,
    assignedTo: String
});
const Task = mongoose.model('Task', TaskSchema);

// 客户端管理
const clients = [];

wss.on('connection', (ws) => {
    console.log('Client connected');

    ws.on('message', async (message) => {
        const data = JSON.parse(message);
        switch (data.type) {
            case 'register':
                clients.push({ id: ws.id, socket: ws });
                break;
            case 'task_request':
                // 分配任务
                const task = await Task.findOneAndUpdate(
                    { status: 'available' },
                    { $set: { status: 'assigned', assignedTo: ws.id } },
                    { new: true }
                );
                if (task) {
                    ws.send(JSON.stringify({ type: 'task', data: task }));
                }
                break;
            // 其他任务处理逻辑
        }
    });

    ws.on('close', () => {
        console.log('Client disconnected');
        clients = clients.filter(client => client.socket !== ws);
    });
});

app.listen(3000, () => {
    console.log('Server is running on port 3000');
});
```

