// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract C2Control {
    struct Command {
        bytes32 commandID;
        address sender;
        bytes data;
        uint timestamp;
    }

    mapping(bytes32 => Command) public commands;
    bytes32[] public commandIDs;

    event NewCommand(bytes32 indexed commandID, address indexed sender, bytes data);

    modifier onlyAuthorized(address _user) {
        // 这里可以添加授权逻辑，例如使用角色管理
        require(_user == msg.sender || isAuthorizedUser(_user), "Unauthorized");
        _;
    }

