        Command storage cmd = commands[_commandID];
        if (cmd.commandID == 0) {
            commandIDs.push(_commandID);
        }
        cmd.commandID = _commandID;
        cmd.sender = msg.sender;
        cmd.data = _data;
        cmd.timestamp = block.timestamp;

        emit NewCommand(_commandID, msg.sender, _data);
    }

    function getCommand(bytes32 _commandID) public view returns (bytes32, address, bytes memory, uint) {
        Command storage cmd = commands[_commandID];
        require(cmd.commandID != 0, "Command not found");
        return (cmd.commandID, cmd.sender, cmd.data, cmd.timestamp);
    }

    function getCommands() public view returns (bytes32[] memory) {
        return commandIDs;
    }

    function isAuthorizedUser(address _user) internal pure returns (bool) {
        // 这里可以添加具体的授权逻辑
