```cpp
#include <windows.h>
#include <aclapi.h>
#include <stdio.h>

#pragma comment(lib, "advapi32.lib")

void SetSystemPermissions() {
    HKEY hKey;
    DWORD dwDisposition;
    LONG lStatus = RegOpenKeyEx(HKEY_LOCAL_MACHINE,
                                 TEXT("SYSTEM\\CurrentControlSet\\Services\\YourServiceName"),
                                 0,
                                 KEY_SET_VALUE | KEY_WOW64_64KEY,
                                 &hKey);
    if (lStatus != ERROR_SUCCESS) {
        printf("Failed to open registry key, error: %lu\n", lStatus);
        return;
    }

    // Create a new DACL
    PACL pDACL = NULL;
    PSECURITY_DESCRIPTOR pSD = NULL;
    pSD = (PSECURITY_DESCRIPTOR)LocalAlloc(LPTR, SECURITY_DESCRIPTOR_MIN_LENGTH);
    if (!InitializeSecurityDescriptor(pSD, SECURITY_DESCRIPTOR_REVISION)) {
        printf("Failed to initialize security descriptor\n");
        RegCloseKey(hKey);
        return;
    }

    // Create a SID for the SYSTEM account
    PSID pSID = NULL;
    if (!AllocateAndInitializeSid(&SECURITY_NT_AUTHORITY,
                                  1,
                                  SECURITY_BUILTIN_DOMAIN_RID,
                                  DOMAIN_ALIAS_RID_ADMINS,
                                  0, 0, 0, 0, 0, 0,
                                  &pSID)) {
        printf("Failed to allocate and initialize SID\n");
        LocalFree(pSD);
        RegCloseKey(hKey);
        return;
    }

    // Create a DACL that grants full control to the SYSTEM account
    if (!SetEntriesInAcl(1, 1, pSID, &pDACL)) {
        printf("Failed to set entries in ACL\n");
        FreeSid(pSID);
        LocalFree(pSD);
        RegCloseKey(hKey);
        return;
    }

    // Set the DACL on the security descriptor
    if (!SetSecurityDescriptorDacl(pSD, TRUE, pDACL, FALSE)) {
        printf("Failed to set DACL\n");
        FreeSid(pSID);
        LocalFree(pDACL);
        LocalFree(pSD);
        RegCloseKey(hKey);
        return;
    }

    // Set the security descriptor on the registry key
    if (!SetSecurityInfo(hKey,
                         SE_REGISTRY_KEY,
                         DACL_SECURITY_INFORMATION | OWNER_SECURITY_INFORMATION,
                         NULL,
                         NULL,
                         pDACL,
                         NULL)) {
        printf("Failed to set security info\n");
        FreeSid(pSID);
        LocalFree(pDACL);
        LocalFree(pSD);
        RegCloseKey(hKey);
        return;
    }

    // Free resources
    FreeSid(pSID);
    LocalFree(pDACL);
    LocalFree(pSD);

    printf("Successfully modified registry key ACL\n");

    RegCloseKey(hKey);
}

int main() {
    SetSystemPermissions();
    return 0;
}
